package org.jsoup.safety;

import org.jsoup.nodes.Attribute;
import org.jsoup.nodes.Attributes;

import java.util.HashMap;
import java.util.Map;

/**
 * Encapsulates the enforced-attribute responsibility previously held in Safelist.
 * Package-level class to allow Safelist and package tests to interact as needed.
 */
class SafelistEnforcedAttributes {
    // using the nested types from Safelist
    private final Map<Safelist.TagName, Map<Safelist.AttributeKey, Safelist.AttributeValue>> enforcedAttributes;

    SafelistEnforcedAttributes() {
        enforcedAttributes = new HashMap<>();
    }

    // copy constructor
    SafelistEnforcedAttributes(SafelistEnforcedAttributes copy) {
        this();
        for (Map.Entry<Safelist.TagName, Map<Safelist.AttributeKey, Safelist.AttributeValue>> entry : copy.enforcedAttributes.entrySet()) {
            this.enforcedAttributes.put(entry.getKey(), new HashMap<>(entry.getValue()));
        }
    }

    SafelistEnforcedAttributes addEnforcedAttribute(String tag, String attribute, String value) {
        Safelist.TagName tagName = Safelist.TagName.valueOf(tag);
        Safelist.AttributeKey attrKey = Safelist.AttributeKey.valueOf(attribute);
        Safelist.AttributeValue attrVal = Safelist.AttributeValue.valueOf(value);

        Map<Safelist.AttributeKey, Safelist.AttributeValue> attrMap = enforcedAttributes.computeIfAbsent(tagName, k -> new HashMap<>());
        attrMap.put(attrKey, attrVal);
        return this;
    }

    SafelistEnforcedAttributes removeEnforcedAttribute(String tag, String attribute) {
        Safelist.TagName tagName = Safelist.TagName.valueOf(tag);
        if (enforcedAttributes.containsKey(tagName)) {
            Safelist.AttributeKey key = Safelist.AttributeKey.valueOf(attribute);
            Map<Safelist.AttributeKey, Safelist.AttributeValue> attrMap = enforcedAttributes.get(tagName);
            attrMap.remove(key);
            if (attrMap.isEmpty()) enforcedAttributes.remove(tagName);
        }
        return this;
    }

    Attributes getEnforcedAttributes(String tagName) {
        Attributes attrs = new Attributes();
        Safelist.TagName tag = Safelist.TagName.valueOf(tagName);
        if (enforcedAttributes.containsKey(tag)) {
            Map<Safelist.AttributeKey, Safelist.AttributeValue> keyVals = enforcedAttributes.get(tag);
            for (Map.Entry<Safelist.AttributeKey, Safelist.AttributeValue> entry : keyVals.entrySet()) {
                attrs.put(entry.getKey().toString(), entry.getValue().toString());
            }
        }
        return attrs;
    }

    // helper accessor used by Safelist internals
    Safelist.AttributeValue getEnforcedValue(Safelist.TagName tag, Safelist.AttributeKey key) {
        Map<Safelist.AttributeKey, Safelist.AttributeValue> attrs = enforcedAttributes.get(tag);
        if (attrs == null) return null;
        return attrs.get(key);
    }

    boolean hasEnforcedAttribute(Safelist.TagName tag, Safelist.AttributeKey key) {
        Map<Safelist.AttributeKey, Safelist.AttributeValue> attrs = enforcedAttributes.get(tag);
        return attrs != null && attrs.containsKey(key);
    }

    // remove all enforced attributes for a tag - helper for Safelist.removeTags
    void removeAll(Safelist.TagName tag) {
        enforcedAttributes.remove(tag);
    }

    // expose internal map for Safelist copy constructor convenience
    Map<Safelist.TagName, Map<Safelist.AttributeKey, Safelist.AttributeValue>> getInternalMap() {
        return enforcedAttributes;
    }
}
